using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Design;
using ReconciliationPlatform.Core;
namespace ReconciliationPlatform.Infrastructure;

public sealed class ReconciliationDbContext(DbContextOptions<ReconciliationDbContext> options) : DbContext(options) { public DbSet<InboxMessage> Inbox => Set<InboxMessage>(); public DbSet<ExceptionCase> Cases => Set<ExceptionCase>(); public DbSet<NotificationMessage> Notifications => Set<NotificationMessage>(); public DbSet<DeadLetter> DeadLetters => Set<DeadLetter>(); protected override void OnModelCreating(ModelBuilder b) { var i = b.Entity<InboxMessage>(); i.HasKey(x => x.MessageId); i.Property(x => x.SourceSystem).HasMaxLength(100); i.Property(x => x.RecordKey).HasMaxLength(200); i.Property(x => x.CorrelationId).HasMaxLength(100); i.HasIndex(x => new { x.ProcessedAt, x.ReceivedAt }); var c = b.Entity<ExceptionCase>(); c.HasKey(x => x.Id); c.Property(x => x.SourceSystem).HasMaxLength(100); c.Property(x => x.RecordKey).HasMaxLength(200); c.Property(x => x.ExpectedAmount).HasPrecision(18, 2); c.Property(x => x.ActualAmount).HasPrecision(18, 2); c.Property(x => x.CorrelationId).HasMaxLength(100); c.HasIndex(x => new { x.SourceSystem, x.RecordKey }).IsUnique(); var n = b.Entity<NotificationMessage>(); n.HasKey(x => x.Id); n.Property(x => x.CorrelationId).HasMaxLength(100); n.Property(x => x.LastError).HasMaxLength(2000); n.HasIndex(x => new { x.SentAt, x.NextAttemptAt }); var d = b.Entity<DeadLetter>(); d.HasKey(x => x.Id); d.Property(x => x.CorrelationId).HasMaxLength(100); d.Property(x => x.Error).HasMaxLength(2000); d.HasIndex(x => x.DeadLetteredAt); } }
public sealed class ReconciliationDbContextFactory : IDesignTimeDbContextFactory<ReconciliationDbContext> { public ReconciliationDbContext CreateDbContext(string[] a) => new(new DbContextOptionsBuilder<ReconciliationDbContext>().UseSqlServer("Server=localhost;Database=ReconciliationPlatform;Trusted_Connection=True;TrustServerCertificate=True").Options); }
